issue_context.body:
#### Expected Behavior
No orders should have `OrderStatus.CancelPending` after calling `Transactions.CancelOpenOrders`.

#### Actual Behavior
The last order submitted in the test algorithm has `OrderStatus.CancelPending`.

#### Potential Solution
The issue seems to be caused by a race condition between `BacktestingBrokerage` and `BrokerageTransactionHandler`, where order cancellation is being attempted _immediately after_ the order is rejected and status is set to `OrderStatus.Invalid` (e.g. insufficient buying power).

#### Reproducing the Problem
This algorithm demonstrates the issue both locally and in the cloud:
``` C#
    public class BasicTemplateAlgorithm : QCAlgorithm
    {
        public override void Initialize()
        {
            SetStartDate(2017, 9, 3);  //Set Start Date
            SetEndDate(2017, 9, 3);    //Set End Date
            SetCash(1000);             //Set Strategy Cash

            SetBrokerageModel(BrokerageName.GDAX, AccountType.Cash);

            AddCrypto("BTCUSD", Resolution.Minute);
            AddCrypto("ETHUSD", Resolution.Minute);
        }

        public override void OnData(Slice data)
        {
            if (UtcTime.Hour != 6) return;

            if (UtcTime.Minute == 0)
            {
                LimitOrder("BTCUSD", 0.10555181m, 4734.64m);
                LimitOrder("ETHUSD", 1.35505027m, 368.8m);
            }
            else if (UtcTime.Minute == 6)
            {
                Transactions.CancelOpenOrders("BTCUSD");
                LimitOrder("BTCUSD", 0.10576312m, 4727.61m);
            }
            else if (UtcTime.Minute == 12)
            {
                Transactions.CancelOpenOrders("BTCUSD");
                LimitOrder("BTCUSD", 0.10576267m, 4727.63m);
            }
            else if (UtcTime.Minute == 18)
            {
                Transactions.CancelOpenOrders("BTCUSD");
                // This order is (correctly) rejected with the following error:
                // Order Error: id: 5, Insufficient buying power to complete order (Value:499.8535), 
                // Reason: Your portfolio holds 500.257460424 USD, 0 USD of which are reserved for open orders, 
                // but your Buy order is for 0.10547724 BTC. Your order requires a total value of 
                // 500.0064180408 USD, but only a total value of 499.007826733893 USD is available.
                LimitOrder("BTCUSD", 0.10547724m, 4740.42m);
            }
            else if (UtcTime.Minute == 24)
            {
                // The following statement leaves the order with OrderStatus.CancelPending
                // Error message: Brokerage failed to cancel order with id 5
                Transactions.CancelOpenOrders("BTCUSD");
            }
        }

        public override void OnOrderEvent(OrderEvent orderEvent)
        {
            Debug(orderEvent.ToString());
        }
    }
```

